entries[73762] = { ["name"] = "Dunkelmond-Ballon", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man diesen Ballon beschwört.\nMit Rechtsklick Euren Dunkelmond-Ballon beschwören oder wieder freigeben.\n80 ( 80)" }
entries[73764] = { ["name"] = "Dunkelmond-Affe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Dunkelmond-Affen beschwören oder wieder freigeben.\n80 ( 80)" }
