entries[73766] = { ["name"] = "Dunkelmond-Tanzbär", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Dunkelmond-Tanzbär oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese furchterregenden Reittiere haben die merkwürdige Eigenschaft, im Kampf plötzlich zu tanzen zu beginnen, was ihre Reiter ausgesprochen störend finden.\"\nVerkäufer:\nLhara\nZone:\nDunkelmond-Insel\nKosten:\n180" }
entries[73782] = { ["name"] = "Instabiler Solenoid", ["text"] = "Questgegenstand\n\"Allein einen davon in Eurer Hand zu halten beunruhigt Euch.\"" }
entries[73791] = { ["name"] = "Sonnenperle", ["text"] = "Questgegenstand\nBenutzen: In die Mitte des Teichs der Reflexion fallenlassen, um Shu, den Geist des Wassers, hervorzulocken." }
entries[73792] = { ["name"] = "Gestohlenes Geschenk", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Winterhauchfest\n\"Da steht Euer Name drauf!\"\n<Zum Öffnen rechtsklicken>" }
