entries[73802] = { ["name"] = "Fass mit geistberührtem Wasser", ["text"] = "Questgegenstand\nBenutzen: Benutzt den Inhalt Eures Fasses mit geistberührtem Wasser, um die Feuer in der Nähe des Zeppelinwracks zu löschen. (3 Sek. Abklingzeit)" }
entries[73837] = { ["name"] = "Improvisierte Sprengladung", ["text"] = "Questgegenstand\nBenutzen: Platziert ein Bündel improvisierte Sprengladung, die 2 Min. lang bestehen bleibt. Improvisierte Sprengladung darf nicht näher als 10 Meter von einer anderen improvisierten Sprengladung platziert werden. (3 Sek. Abklingzeit)\n\"Sieht ein wenig instabil aus...\"" }
entries[73838] = { ["name"] = "Bergpferd", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares Bergpferd oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Abbildungen dieser Spezies befinden sich oft auf Fässern von verwässertem Zwergenbräu.\"\nVerkäufer:\nAstrid Langstrumpf\nZone:\nDarnassus\nKosten:" }
entries[73839] = { ["name"] = "Schnelles Bergpferd", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares schnelles Bergpferd oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Sehnt sich nach dem Tag, an dem es zu seinem Heim in Gilneas zurückkehren kann.\"\nVerkäufer:\nAstrid Langstrumpf\nZone:\nDarnassus\nKosten:" }
