entries[74142] = { ["name"] = "Dunkelmond-Feuerwerk", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Schießt eine Feuerwerksrakete ab, die in Form des Wappens des Dunkelmond-Jahrmarkts explodiert.\nBenötigt Dunkelmond-Jahrmarkt\nVerkaufspreis:" }
entries[74160] = { ["name"] = "Zin'Juns Gewehr", ["text"] = "Questgegenstand\nEinzigartig\n\"Der Mechanismus ist mit... 'Dreck' verkrustet, wodurch die Waffe nutzlos geworden ist.\"" }
