entries[74162] = { ["name"] = "Zin'Juns rechtes Auge", ["text"] = "Questgegenstand\nEinzigartig\n\"Dank des Ausschlussverfahrens könnt Ihr davon ausgehen, dass dies Zin'Juns 'Auge zum Schießen' ist.\"" }
