entries[74258] = { ["name"] = "Stab von Pei-Zhi", ["text"] = "Questgegenstand\n\"Nach all diesen Jahren irgendwie noch stabil...\"" }
entries[74260] = { ["name"] = "Bambusschlüssel", ["text"] = "Questgegenstand\nBenutzen: Öffnet Bambuskäfige, um Jinyu- und Allianzgefangene zu befreien.\n\"Es ist ein Wunder, dass dieses zarte Ästchen überhaupt irgendetwas öffnen kann.\"" }
entries[74269] = { ["name"] = "Flammender Hippogryph", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren flammenden Hippogryphen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Hippogryphen sind hochintelligente, denkende Wesen und nicht nur einfache \"Reittiere\".\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht\nHandelsposten" }
entries[74274] = { ["name"] = "Pläne: Phantomklinge", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch das Schmieden einer Phantomklinge.\nBenötigt Klassische Schmiedekunst (270)\n\nPhantomklinge\nWird beim Anlegen gebunden\nEinhändig Schwert\n3 - 6 Schaden Geschwindigkeit 2.60\n(1.7 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\nTrefferchance: Verringert die Rüstung des Ziels 20 Sek. lang um 22 . Während der Wirkungsdauer kann das Ziel weder Verstohlenheit anwenden noch unsichtbar werden.\nVerkaufspreis:\nBenötigt Mithrilbarren (28), Odem des Windes (6), Echtsilberbarren (8), Geringer Unsichtbarkeitstrank (2), Aquamarin (6), Robuster Schleifstein (4), Dickes Leder (2)\nOptionale Reagenzien: [] (#49)" }
