entries[74663] = { ["name"] = "Rezept: Gegrilltes Tigersteak", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man gegrilltes Tigersteak zubereitet.\nKöstlich!\nBenötigt Kochkunst von Pandaria (1)\nVerkaufspreis:\nGegrilltes Tigersteak\nBenutzen: Stellt im Verlauf von 20 Sek. 4340 Gesundheit und ( 1118 / 5 * 10) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 9 Stärke.\nVerkaufspreis:\nBenötigt Rohes Tigersteak" }
entries[74664] = { ["name"] = "Rezept: Blütenfischfilet", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Blütenfischfilet zubereitet.\nBenötigt Kochkunst von Pandaria (25)\nVerkaufspreis:\nBlütenfischfilet\nBenutzen: Stellt im Verlauf von 20 Sek. 21682 Gesundheit und ( 5000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 15 Stärke.\nVerkaufspreis:\nBenötigt Jadelungenfisch , Streifenmelone (5)" }
