entries[74723] = { ["name"] = "Waffe - Windweise", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Heilungen oder Schaden verursachenden Zauber und Nahkampfangriffe manchmal Eure Meisterschaft, Euer Tempo oder Euren kritischen Trefferwert 12 Sek. lang um 31 erhöhen. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:" }
entries[74724] = { ["name"] = "Waffe - Jadegeist", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Heilungen oder Schaden verursachenden Zauber manchmal Eure Intelligenz um 34 erhöhen. Wenn Ihr über weniger als 25% Mana verfügt, während dieser Effekt ausgelöst wird, wird Eure Vielseitigkeit ebenfalls um 16 erhöht. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:" }
entries[74725] = { ["name"] = "Waffe - Elementarkraft", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Schaden verursachenden Nahkampfangriffe und Zauber manchmal zusätzlich 112 Elementarschaden verursachen. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:" }
entries[74726] = { ["name"] = "Waffe - Tanzender Stahl", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Schaden verursachenden Nahkampfangriffe manchmal Eure Stärke oder Beweglichkeit um 43 erhöhen. Der höhere der beiden Werte wird gewählt. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:" }
entries[74727] = { ["name"] = "Waffe - Koloss", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Schaden verursachenden Nahkampfangriffe manchmal einen Schutzzauber der Mogu auslösen, der bis zu 17904 erlittenen Schaden absorbiert. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:" }
entries[74728] = { ["name"] = "Waffe - Flussgesang", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Schaden verursachenden Nahkampfangriffe manchmal Euer Ausweichen 7 Sek. lang um 34 erhöhen. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:" }
entries[74729] = { ["name"] = "Schildhand - Erhebliche Intelligenz", ["text"] = "Benutzen: Einen Schild oder Gegenstand für die Schildhand dauerhaft verzaubern, sodass die Intelligenz um 11 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nVerkaufspreis:" }
entries[74748] = { ["name"] = "Aufgeladener Entschlüsselungsring", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Entschlüsselt die angesengte Chiffre.\n\"Vollständig mit arkaner Energie aufgeladen.\"" }
entries[74749] = { ["name"] = "Aufladender Entschlüsselungsring", ["text"] = "Questgegenstand\nEinzigartig\nDauer: 12 std. (Realzeit)\n\"Ein leichtes Glühen zeigt an, dass der Ring sich gerade auflädt.\"" }
entries[74750] = { ["name"] = "Angesengte Geheimnachricht", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Runen, aus der diese Geheimnachricht besteht, scheinen sich ständig zu verändern.\"" }
entries[74752] = { ["name"] = "Gelöste Geheimnachricht", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine entschlüsselte Nachricht von den Schurken, die den roten Drachenschwarm infiltriert haben!\"\n<Zum Lesen rechtsklicken>" }
entries[74755] = { ["name"] = "König Dreds Zahn", ["text"] = "Questgegenstand\n\"Dieser gewaltige Zahn würde ohne weiteres eine passable Waffe abgeben.\"" }
entries[74760] = { ["name"] = "Gesprungene Ritualschale", ["text"] = "Questgegenstand\n\"Konzentrische Kreise verzieren die Innenseite der ansonsten unscheinbaren Lehmschale.\"" }
entries[74761] = { ["name"] = "Geruchsintensive Ritualkerze", ["text"] = "Questgegenstand\n\"Räucherwerk, zerstoßene Kräuter und Mineralstaub wurden in das Wachs eingearbeitet, wodurch ein kräftiger Duft und eine helle Flamme entsteht.\"" }
entries[74762] = { ["name"] = "Jadecong", ["text"] = "Questgegenstand\n\"Ein quadratischer Zylinder mit aufwendigen Schnitzereien auf jeder Seite.\"" }
entries[74763] = { ["name"] = "Geisterflasche", ["text"] = "Questgegenstand\n\"Eine Gravur auf der Flasche besagt: 'Der Körper ist nur ein Gefäß. Die Klaue sucht, was sich in ihm versteckt.'\"" }
entries[74768] = { ["name"] = "Unlesbare Schriftrolle", ["text"] = "Wird beim Aufheben gebunden\n\"Fremdartige Markierungen bilden auf diesem Pergament ein hypnotisierendes Muster.\"" }
entries[74771] = { ["name"] = "Stab von Pei-Zhi", ["text"] = "Questgegenstand\nBenutzen: Zieht einen verirrten Urahnen in den Stab. Kann sich während der Kanalisierung bewegen." }
entries[74783] = { ["name"] = "Eroberungsrelikt des kataklysmischen Gladiators", ["text"] = "Saison 11 (Elite)\nWird beim Aufheben gebunden\nVerkaufspreis:" }
