entries[74786] = { ["name"] = "Triumphales Relikt des kataklysmischen Gladiators", ["text"] = "Saison 11 (Elite)\nWird beim Aufheben gebunden\nVerkaufspreis:" }
entries[74808] = { ["name"] = "Geisterflasche", ["text"] = "Questgegenstand\nBenutzen: Wirft eine Geisterflasche, um sie zu zerschmettern und den Geist im Inneren zu befreien. (6 Sek. Abklingzeit)" }
entries[74812] = { ["name"] = "Verdünntes Kalziumoxidsulfur", ["text"] = "Questgegenstand\n\"Eine giftige Lösung, die sowohl Eure Freunde vertreibt als auch alles tötet, was in Euren Haaren lebt.\"\nVerkaufspreis:" }
entries[74813] = { ["name"] = "Hartriegelextrakt", ["text"] = "Questgegenstand\n\"Ein Extrakt des Hartriegelstrauchs, mit dem Tiere gewaschen werden, die von der Krätze befallen sind.\"\nVerkaufspreis:" }
entries[74815] = { ["name"] = "Beruhigendes Shampoo", ["text"] = "Questgegenstand\n\"Mit der speziellen Formel zur Beruhigung von empfindlicher und gereizter Haut.\"\nVerkaufspreis:" }
entries[74822] = { ["name"] = "Sarsaparilla-Bombe", ["text"] = "Benutzen: Stellt im Verlauf von 30 Sek. insgesamt ( 1375 / 5 * 30) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\"Eine sprudelnde Sarsaparilla mit Vanilleeiskugeln.\"\nVerkaufspreis:" }
entries[74830] = { ["name"] = "Kristallene Träne der Trauer", ["text"] = "Questgegenstand\n\"Wenn Ihr diesen Kristall in den Händen haltet, durchfließen Euch Erinnerungen aller traurigen Momente Eures Lebens.\"" }
