entries[74981] = { ["name"] = "Dunkelmond-Junges", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euer Dunkelmond-Junges beschwören oder wieder freigeben.\n80 ( 80)" }
