entries[75016] = { ["name"] = "Großes Pandarenfestmahl", ["text"] = "Benutzen: Richtet ein großes Pandarenfestmahl her, das bis zu 30 Leute in Eurem Schlachtzug oder Eurer Gruppe sättigen kann!\n\nStellt im Verlauf von 20 Sek. 21682 Gesundheit und ( 5000 / 5 * 20) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein für Euch nützlicher Wert wird 1 Stunde lang um 15 erhöht.\nVerkaufspreis:" }
entries[75017] = { ["name"] = "Rezept: Großes Pandarenfestmahl", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein großes Pandarenfestmahl zubereitet.\nBenötigt Kochkunst von Pandaria (75)\nIhr müsst zunächst die Quest \"Pflichten eines Meisters\" abgeschlossen haben.\nVerkaufspreis:\nGroßes Pandarenfestmahl\nBenutzen: Richtet ein großes Pandarenfestmahl her, das bis zu 30 Leute in Eurem Schlachtzug oder Eurer Gruppe sättigen kann!\n\nStellt im Verlauf von 20 Sek. 21682 Gesundheit und ( 5000 / 5 * 20) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein für Euch nützlicher Wert wird 1 Stunde lang um 15 erhöht.\nVerkaufspreis:\nBenötigt Hundert Jahre alte Sojasoße , Juwelendanio (20), Rohes Tigersteak (20), Rosa Rübe (100)" }
