entries[75202] = { ["name"] = "Bachsaibling", ["text"] = "Questgegenstand\n\"So schleimig wie tüpfelig.\"" }
entries[75208] = { ["name"] = "Viehhüterlasso", ["text"] = "Questgegenstand\nBenutzen: Versucht, mit dem Viehhüterlasso einen großen weißen Ebenenfalken einzufangen." }
entries[75212] = { ["name"] = "Unbeschädigter Tonkrug", ["text"] = "Questgegenstand\n\"Der Hals des Kruges ist groß genug, dass ein Fisch oder die Hand eines Ho-zen hindurchpasst, jedoch nicht beides zur gleichen Zeit.\"" }
entries[75214] = { ["name"] = "Gezeitennebelkappe", ["text"] = "Questgegenstand\n\"Dieser Pilz gibt ein schwaches Schimmern ab und ist durch die Feuchtigkeit angeschwollen.\"" }
entries[75217] = { ["name"] = "Zenlotus", ["text"] = "Questgegenstand\n\"Die schönen Blumen haben ein wundervolles Aroma. Atmet tief durch und findet Eure innere Ruhe...\"" }
entries[75218] = { ["name"] = "Elektrifiziertes Öl", ["text"] = "Benutzen: Lädt Euch einige Sekunden lang auf. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[75219] = { ["name"] = "Frisch gefallenes Blütenblatt", ["text"] = "Questgegenstand\n\"Frisch gefallen und von perfekter Färbung.\"" }
entries[75220] = { ["name"] = "Ho-zen-Falle", ["text"] = "Questgegenstand\nBenutzen: Platziert die Ho-zen-Falle im Lager Nuka-Nuka. Sie zieht in der Nähe befindliche Ho-zen an und fängt sie. (10 Sek. Abklingzeit)\n\"Nass, feucht und riecht nach Fisch.\"" }
entries[75221] = { ["name"] = "Wespenstachel", ["text"] = "Questgegenstand\n\"Ein scharfer, länglicher Stachel, der einfach ideal ist, um zu einer Schreibfeder verarbeitet zu werden.\"" }
entries[75256] = { ["name"] = "Pangs besonders scharfer Tofu", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein ungeheuerlich großer Topf voller Tofu. Es wird nicht leicht sein, ihn den Berg hinab zu befördern.\"" }
entries[75258] = { ["name"] = "Angs Sommerwassermelone", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein wenig unhandlich und schwierig zu tragen.\"" }
entries[75259] = { ["name"] = "Angs riesige rosa Rübe", ["text"] = "Questgegenstand\nEinzigartig\n\"Sie ist gewaltig!\"" }
entries[75271] = { ["name"] = "Jian", ["text"] = "Questgegenstand\nEinzigartig\n\"Überraschenderweise scheint er recht zufrieden damit zu sein, in Eurer Tasche herumgetragen zu werden.\"" }
entries[75272] = { ["name"] = "Ling", ["text"] = "Questgegenstand\nEinzigartig\n\"Ihre Haut ist von einem feinen, weißen Flaum bedeckt und ihr Rücken ist ein wenig länger als bei gewöhnlichen Schweinen.\"" }
entries[75273] = { ["name"] = "Stinki", ["text"] = "Questgegenstand\nEinzigartig\n\"Er macht seinem Namen alle Ehre.\"" }
entries[75274] = { ["name"] = "Meditativer Alchemistenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)\nSchmuck\nErhöht Eure Meisterschaftswertung um + 6.\nAnlegen: Ihr habt eine Chance, bei hervorgerufener Heilung oder verursachtem Schaden Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 21 zu erhöhen. Es wird stets Euer höchster Wert gewählt. (Procchance: 35%, 55s Abklingzeit)\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie von Pandaria\n(1)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:" }
entries[75275] = { ["name"] = "Mushanschulterstück", ["text"] = "Questgegenstand\n\"Dunkles Muskelfleisch von der Schulter, mit einem pikanten Geruch. Es ist nicht sonderlich appetitanregend.\"" }
entries[75276] = { ["name"] = "Schildkrötenfleischfetzen", ["text"] = "Questgegenstand\n\"Gut mit Fett durchwachsen. Sie haben einen leichten Wildgeruch.\"" }
entries[75525] = { ["name"] = "Fläschchen des Alchemisten", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhöht Eure Beweglichkeit, Stärke oder Intelligenz 2 Stunden lang um 12 . Es wird immer Euer höchster Wert gewählt.\n\nGilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nFunktioniert nicht auf Stufe 49 oder höher.\nBenötigt Klassische Alchemie\n(1)\n\"Dieses mächtige Fläschchen wird bei der Verwendung nicht verbraucht.\"" }
