entries[76062] = { ["name"] = "Speer des Fetischschamanen", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man einen Fetischschamanen beschwört.\nMit Rechtsklick Euren Fetischschamanen beschwören oder wieder freigeben.\n80 ( 80)" }
